/* Shader heap address reuse: a new shader written over a freed shader's range must be what
 * the GPU executes.
 *
 * Each iteration creates a graphics pipeline from one of REUSE_NV vertex and REUSE_NF
 * fragment shaders (exact unrolled integer chains of different lengths, generated by
 * vk-shader-reuse-gen.py) through a fresh VkPipelineCache, draws one full-screen triangle
 * into an R32_UINT target, waits, checks every pixel against the CPU value and destroys the
 * pipeline and the cache. Destroying both frees the shaders' heap ranges, so the next
 * pipeline's program headers and code land over memory the GPU executed one submission
 * earlier. A stale program header shows up as Xid 13 "Shader Program Header N Error" in the
 * kernel log (VK_ERROR_DEVICE_LOST here); stale code shows up as wrong pixels.
 *
 * With FRAMES > 1, FRAMES submissions are kept in flight (one target, pipeline and cache per frame slot)
 * and a slot's pipeline is destroyed only after its fence signalled, while the GPU still executes the
 * other frames: shader ranges are recycled and rewritten while the queue never idles, as in ANGLE.
 *
 * Usage: vk-shader-reuse [ITERATIONS [SEED [FRAMES [SIZE]]]]   (default 2000, seed 1, 1 frame, 32x32)
 * The GPU is picked by vendor ID 0x10de, the driver with VK_DRIVER_FILES.
 *
 * Build (see tests/README.md "vk-shader-reuse"):
 *   python3 vk-shader-reuse-gen.py OUT && cc -std=c11 -O2 -Wall -Wextra -Werror -IOUT \
 *     vk-shader-reuse.c -lvulkan -o OUT/vk-shader-reuse
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <vulkan/vulkan.h>
#include "vk-shader-reuse.spv.h"

#define VKCHECK(call) do { VkResult r_ = (call); if (r_ != VK_SUCCESS) { \
   fprintf(stderr, "FATAL %s:%d %s -> %d\n", __FILE__, __LINE__, #call, r_); exit(2); } } while (0)

static uint32_t W = 32, H = 32;
#define MAX_FRAMES 16

static uint32_t
cpu_chain(uint32_t x, uint32_t n, uint32_t salt)
{
   for (uint32_t i = 0; i < n; i++)
      x = (x ^ (x >> 13)) * 1664525u + (uint32_t)((i * 7919 + salt * 31 + 17) % 65521);
   return x;
}

static uint32_t
expect(uint32_t kv, uint32_t kf)
{
   uint32_t v = cpu_chain(kv + 1, vs_len[kv], 1000 + kv);
   return cpu_chain(v + kf, fs_len[kf], 2000 + kf);
}

static uint32_t
find_mem(VkPhysicalDevice pd, uint32_t bits, VkMemoryPropertyFlags want)
{
   VkPhysicalDeviceMemoryProperties mp;
   vkGetPhysicalDeviceMemoryProperties(pd, &mp);
   for (uint32_t i = 0; i < mp.memoryTypeCount; i++)
      if ((bits & (1u << i)) && (mp.memoryTypes[i].propertyFlags & want) == want)
         return i;
   fprintf(stderr, "no memory type for bits 0x%x flags 0x%x\n", bits, want);
   exit(2);
}

struct frame {
   VkImage img;
   VkDeviceMemory imem;
   VkImageView view;
   VkBuffer buf;
   VkDeviceMemory bmem;
   uint32_t *px;
   VkCommandBuffer cb;
   VkFence fence;
   VkPipeline pipe;
   VkPipelineCache cache;
   uint32_t kv, kf;
   unsigned it;
   int busy;
};

static unsigned bad_iters;

/* Wait for a frame's submission, check its pixels and free its pipeline (returning the shaders' heap
 * ranges). Returns 0 on fence failure (device lost: see the kernel log for the Xid). */
static int
retire(VkDevice dev, struct frame *f)
{
   if (!f->busy)
      return 1;
   VkResult wr = vkWaitForFences(dev, 1, &f->fence, VK_TRUE, 10ull * 1000 * 1000 * 1000);
   if (wr != VK_SUCCESS) {
      printf("FAIL iteration %u (vs %u fs %u): fence wait -> %d (see kernel log for Xid)\n", f->it, f->kv, f->kf, wr);
      return 0;
   }
   VKCHECK(vkResetFences(dev, 1, &f->fence));
   const uint32_t want = expect(f->kv, f->kf);
   unsigned bad = 0;
   for (uint32_t i = 0; i < W * H; i++)
      bad += f->px[i] != want;
   if (bad) {
      if (bad_iters < 10)
         printf("iteration %u (vs %u fs %u): %u/%u pixels wrong, px[0]=0x%08x want 0x%08x\n",
                f->it, f->kv, f->kf, bad, W * H, f->px[0], want);
      bad_iters++;
   }
   vkDestroyPipeline(dev, f->pipe, NULL);
   vkDestroyPipelineCache(dev, f->cache, NULL);
   f->busy = 0;
   return 1;
}

int
main(int argc, char **argv)
{
   const unsigned iters = argc > 1 ? (unsigned)strtoul(argv[1], NULL, 0) : 2000;
   uint32_t rng = argc > 2 ? (uint32_t)strtoul(argv[2], NULL, 0) : 1;
   const unsigned nframes = argc > 3 ? (unsigned)strtoul(argv[3], NULL, 0) : 1;
   if (argc > 4)
      W = H = (uint32_t)strtoul(argv[4], NULL, 0);
   if (nframes < 1 || nframes > MAX_FRAMES || W < 1 || W > 4096) {
      fprintf(stderr, "usage: %s [ITERATIONS [SEED [FRAMES 1..%d [SIZE 1..4096]]]]\n", argv[0], MAX_FRAMES);
      return 2;
   }

   VkApplicationInfo app = { .sType = VK_STRUCTURE_TYPE_APPLICATION_INFO,
      .pApplicationName = "vk-shader-reuse", .apiVersion = VK_API_VERSION_1_3 };
   VkInstanceCreateInfo ici = { .sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO, .pApplicationInfo = &app };
   VkInstance inst;
   VKCHECK(vkCreateInstance(&ici, NULL, &inst));

   uint32_t n = 16;
   VkPhysicalDevice pds[16];
   VkResult er = vkEnumeratePhysicalDevices(inst, &n, pds);
   if (er != VK_SUCCESS && er != VK_INCOMPLETE) VKCHECK(er);
   VkPhysicalDevice pd = VK_NULL_HANDLE;
   VkPhysicalDeviceDriverProperties drv = { .sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_DRIVER_PROPERTIES };
   for (uint32_t i = 0; i < n; i++) {
      VkPhysicalDeviceProperties2 p = { .sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2, .pNext = &drv };
      vkGetPhysicalDeviceProperties2(pds[i], &p);
      if (p.properties.vendorID == 0x10de) { pd = pds[i]; break; }
   }
   if (pd == VK_NULL_HANDLE) { fprintf(stderr, "no NVIDIA (0x10de) Vulkan device\n"); return 2; }
   printf("driver: %s (%s), %u iterations, seed %u, %u frames in flight, %ux%u\n",
          drv.driverName, drv.driverInfo, iters, rng, nframes, W, H);

   uint32_t qn = 16;
   VkQueueFamilyProperties qp[16];
   vkGetPhysicalDeviceQueueFamilyProperties(pd, &qn, qp);
   uint32_t qf = UINT32_MAX;
   for (uint32_t i = 0; i < qn; i++)
      if (qp[i].queueFlags & VK_QUEUE_GRAPHICS_BIT) { qf = i; break; }
   if (qf == UINT32_MAX) { fprintf(stderr, "no graphics queue\n"); return 2; }

   float prio = 1.0f;
   VkDeviceQueueCreateInfo qci = { .sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO,
      .queueFamilyIndex = qf, .queueCount = 1, .pQueuePriorities = &prio };
   VkPhysicalDeviceVulkan13Features f13 = { .sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_3_FEATURES,
      .dynamicRendering = VK_TRUE };
   VkDeviceCreateInfo dci = { .sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO, .pNext = &f13,
      .queueCreateInfoCount = 1, .pQueueCreateInfos = &qci };
   VkDevice dev;
   VKCHECK(vkCreateDevice(pd, &dci, NULL, &dev));
   VkQueue q;
   vkGetDeviceQueue(dev, qf, 0, &q);

   VkCommandPoolCreateInfo cpci = { .sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO,
      .flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT, .queueFamilyIndex = qf };
   VkCommandPool pool;
   VKCHECK(vkCreateCommandPool(dev, &cpci, NULL, &pool));

   /* One render target, readback buffer, command buffer and fence per frame slot. */
   struct frame frames[MAX_FRAMES];
   memset(frames, 0, sizeof(frames));
   for (unsigned fi = 0; fi < nframes; fi++) {
      struct frame *f = &frames[fi];
      VkImageCreateInfo imci = { .sType = VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO, .imageType = VK_IMAGE_TYPE_2D,
         .format = VK_FORMAT_R32_UINT, .extent = { W, H, 1 }, .mipLevels = 1, .arrayLayers = 1,
         .samples = VK_SAMPLE_COUNT_1_BIT, .tiling = VK_IMAGE_TILING_OPTIMAL,
         .usage = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT };
      VKCHECK(vkCreateImage(dev, &imci, NULL, &f->img));
      VkMemoryRequirements mr;
      vkGetImageMemoryRequirements(dev, f->img, &mr);
      VkMemoryAllocateInfo mai = { .sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO, .allocationSize = mr.size,
         .memoryTypeIndex = find_mem(pd, mr.memoryTypeBits, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT) };
      VKCHECK(vkAllocateMemory(dev, &mai, NULL, &f->imem));
      VKCHECK(vkBindImageMemory(dev, f->img, f->imem, 0));
      VkImageViewCreateInfo ivci = { .sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO, .image = f->img,
         .viewType = VK_IMAGE_VIEW_TYPE_2D, .format = VK_FORMAT_R32_UINT,
         .subresourceRange = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1 } };
      VKCHECK(vkCreateImageView(dev, &ivci, NULL, &f->view));
      VkBufferCreateInfo bci = { .sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO, .size = (VkDeviceSize)W * H * 4,
         .usage = VK_BUFFER_USAGE_TRANSFER_DST_BIT };
      VKCHECK(vkCreateBuffer(dev, &bci, NULL, &f->buf));
      vkGetBufferMemoryRequirements(dev, f->buf, &mr);
      mai.allocationSize = mr.size;
      mai.memoryTypeIndex = find_mem(pd, mr.memoryTypeBits,
         VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
      VKCHECK(vkAllocateMemory(dev, &mai, NULL, &f->bmem));
      VKCHECK(vkBindBufferMemory(dev, f->buf, f->bmem, 0));
      VKCHECK(vkMapMemory(dev, f->bmem, 0, VK_WHOLE_SIZE, 0, (void **)&f->px));
      VkCommandBufferAllocateInfo cbai = { .sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO,
         .commandPool = pool, .level = VK_COMMAND_BUFFER_LEVEL_PRIMARY, .commandBufferCount = 1 };
      VKCHECK(vkAllocateCommandBuffers(dev, &cbai, &f->cb));
      VkFenceCreateInfo fci = { .sType = VK_STRUCTURE_TYPE_FENCE_CREATE_INFO };
      VKCHECK(vkCreateFence(dev, &fci, NULL, &f->fence));
   }

   VkShaderModule vsm[REUSE_NV], fsm[REUSE_NF];
   for (int k = 0; k < REUSE_NV; k++) {
      VkShaderModuleCreateInfo smci = { .sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,
         .codeSize = vs_size[k], .pCode = vs_code[k] };
      VKCHECK(vkCreateShaderModule(dev, &smci, NULL, &vsm[k]));
   }
   for (int k = 0; k < REUSE_NF; k++) {
      VkShaderModuleCreateInfo smci = { .sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,
         .codeSize = fs_size[k], .pCode = fs_code[k] };
      VKCHECK(vkCreateShaderModule(dev, &smci, NULL, &fsm[k]));
   }

   VkPipelineLayoutCreateInfo plci = { .sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO };
   VkPipelineLayout layout;
   VKCHECK(vkCreatePipelineLayout(dev, &plci, NULL, &layout));

   const VkFormat fmt = VK_FORMAT_R32_UINT;
   VkPipelineRenderingCreateInfo prci = { .sType = VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO,
      .colorAttachmentCount = 1, .pColorAttachmentFormats = &fmt };
   VkPipelineVertexInputStateCreateInfo vi = { .sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO };
   VkPipelineInputAssemblyStateCreateInfo ia = { .sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO,
      .topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST };
   VkViewport vp = { 0, 0, (float)W, (float)H, 0, 1 };
   VkRect2D sc = { { 0, 0 }, { W, H } };
   VkPipelineViewportStateCreateInfo vps = { .sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO,
      .viewportCount = 1, .pViewports = &vp, .scissorCount = 1, .pScissors = &sc };
   VkPipelineRasterizationStateCreateInfo rs = { .sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO,
      .polygonMode = VK_POLYGON_MODE_FILL, .cullMode = VK_CULL_MODE_NONE, .lineWidth = 1.0f };
   VkPipelineMultisampleStateCreateInfo ms = { .sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO,
      .rasterizationSamples = VK_SAMPLE_COUNT_1_BIT };
   VkPipelineColorBlendAttachmentState cba = { .colorWriteMask = 0xf };
   VkPipelineColorBlendStateCreateInfo cbs = { .sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO,
      .attachmentCount = 1, .pAttachments = &cba };

   for (unsigned it = 0; it < iters; it++) {
      struct frame *f = &frames[it % nframes];
      if (!retire(dev, f))
         return 1;

      rng = rng * 1103515245u + 12345u;
      f->kv = (rng >> 8) % REUSE_NV;
      rng = rng * 1103515245u + 12345u;
      f->kf = (rng >> 8) % REUSE_NF;
      f->it = it;

      VkPipelineCacheCreateInfo pcci = { .sType = VK_STRUCTURE_TYPE_PIPELINE_CACHE_CREATE_INFO };
      VKCHECK(vkCreatePipelineCache(dev, &pcci, NULL, &f->cache));
      VkPipelineShaderStageCreateInfo st[2] = {
         { .sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, .stage = VK_SHADER_STAGE_VERTEX_BIT,
           .module = vsm[f->kv], .pName = "main" },
         { .sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, .stage = VK_SHADER_STAGE_FRAGMENT_BIT,
           .module = fsm[f->kf], .pName = "main" },
      };
      VkGraphicsPipelineCreateInfo gpci = { .sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO,
         .pNext = &prci, .stageCount = 2, .pStages = st, .pVertexInputState = &vi,
         .pInputAssemblyState = &ia, .pViewportState = &vps, .pRasterizationState = &rs,
         .pMultisampleState = &ms, .pColorBlendState = &cbs, .layout = layout };
      VKCHECK(vkCreateGraphicsPipelines(dev, f->cache, 1, &gpci, NULL, &f->pipe));

      VkCommandBuffer cb = f->cb;
      VkCommandBufferBeginInfo cbbi = { .sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO,
         .flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT };
      VKCHECK(vkBeginCommandBuffer(cb, &cbbi));
      VkImageMemoryBarrier b0 = { .sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER,
         .dstAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT,
         .oldLayout = VK_IMAGE_LAYOUT_UNDEFINED, .newLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL,
         .srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED, .dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED,
         .image = f->img, .subresourceRange = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1 } };
      vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT, VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,
                           0, 0, NULL, 0, NULL, 1, &b0);
      VkRenderingAttachmentInfo att = { .sType = VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO,
         .imageView = f->view, .imageLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL,
         .loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR, .storeOp = VK_ATTACHMENT_STORE_OP_STORE,
         .clearValue = { .color = { .uint32 = { 0xdeadbeef, 0, 0, 0 } } } };
      VkRenderingInfo ri = { .sType = VK_STRUCTURE_TYPE_RENDERING_INFO, .renderArea = sc, .layerCount = 1,
         .colorAttachmentCount = 1, .pColorAttachments = &att };
      vkCmdBeginRendering(cb, &ri);
      vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, f->pipe);
      vkCmdDraw(cb, 3, 1, 0, 0);
      vkCmdEndRendering(cb);
      VkImageMemoryBarrier b1 = b0;
      b1.srcAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
      b1.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
      b1.oldLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
      b1.newLayout = VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;
      vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT, VK_PIPELINE_STAGE_TRANSFER_BIT,
                           0, 0, NULL, 0, NULL, 1, &b1);
      VkBufferImageCopy bic = { .imageSubresource = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1 },
         .imageExtent = { W, H, 1 } };
      vkCmdCopyImageToBuffer(cb, f->img, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, f->buf, 1, &bic);
      VkBufferMemoryBarrier b2 = { .sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER,
         .srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT, .dstAccessMask = VK_ACCESS_HOST_READ_BIT,
         .srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED, .dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED,
         .buffer = f->buf, .size = VK_WHOLE_SIZE };
      vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_TRANSFER_BIT, VK_PIPELINE_STAGE_HOST_BIT,
                           0, 0, NULL, 1, &b2, 0, NULL);
      VKCHECK(vkEndCommandBuffer(cb));

      VkSubmitInfo si = { .sType = VK_STRUCTURE_TYPE_SUBMIT_INFO, .commandBufferCount = 1, .pCommandBuffers = &cb };
      VKCHECK(vkQueueSubmit(q, 1, &si, f->fence));
      f->busy = 1;
   }
   for (unsigned fi = 0; fi < nframes; fi++)
      if (!retire(dev, &frames[fi]))
         return 1;

   VKCHECK(vkDeviceWaitIdle(dev));
   printf("%s: %u/%u iterations with wrong pixels\n", bad_iters ? "FAIL" : "PASS", bad_iters, iters);

   /* Full teardown: device destruction is part of the path under test (heap and upload queue
    * teardown) and lets an armed command-stream capture finish its file. */
   vkDestroyPipelineLayout(dev, layout, NULL);
   for (int k = 0; k < REUSE_NV; k++)
      vkDestroyShaderModule(dev, vsm[k], NULL);
   for (int k = 0; k < REUSE_NF; k++)
      vkDestroyShaderModule(dev, fsm[k], NULL);
   for (unsigned fi = 0; fi < nframes; fi++) {
      struct frame *f = &frames[fi];
      vkDestroyFence(dev, f->fence, NULL);
      vkUnmapMemory(dev, f->bmem);
      vkDestroyBuffer(dev, f->buf, NULL);
      vkFreeMemory(dev, f->bmem, NULL);
      vkDestroyImageView(dev, f->view, NULL);
      vkDestroyImage(dev, f->img, NULL);
      vkFreeMemory(dev, f->imem, NULL);
   }
   vkDestroyCommandPool(dev, pool, NULL);
   vkDestroyDevice(dev, NULL);
   vkDestroyInstance(inst, NULL);
   return bad_iters ? 1 : 0;
}
